    ],
  }).value;

  const text = renderInvoiceText(invoice);

  // LOGO-PACK: 10 * 120000 = 1200000 cents, bulk discount = 30000, net = 1170000, VAT 21% = €2,457.00
  assert.match(text, /10 x Logo package @ €1,200\.00 = €12,000\.00/);
  // BRAND-BOOK: 5 * 245000 = 1225000 cents, no bulk, VAT 21% = €2,572.50
  assert.match(text, /5 x Brand guidelines document @ €2,450\.00 = €12,250\.00/);
  // VAT: 2457.00 + 2572.50 = 5029.50
  assert.match(text, /VAT: €5,029\.50/);
  // Total: 12000 + 12250 - 300 + 5029.50 = 28979.50
  assert.match(text, /Total: €28,979\.50$/);
});

