  // Subtotal: 10 * 9500 = 95000 cents = €950.00
  // Line discount: 95000 * 10 / 100 = 9500 cents, net = 85500
  // Bulk discount: 2.5% of 85500 = 2138 cents
  // Total discount: 11638 cents = €116.38
  // Net after discount: 83362 cents
  // VAT: 21% of 83362 = 17506 cents = €175.06
  // Total: 950 - 116.38 + 175.06 = €1,008.68
  assert.match(text, /10 x Development \(hour\) @ €95\.00 = €950\.00/);
  assert.match(text, /VAT: €175\.0[56]/);
