test('renderInvoiceText shows cumulative paid amount with multiple payments', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const paid1 = recordPayment(issued, { amount: 3000, date: '2026-10-10' }).value;
  const paid2 = recordPayment(paid1, { amount: 4000, date: '2026-10-15' }).value;

  const text = renderInvoiceText(paid2);

  // Should show total paid (3000 + 4000 = 7000)
  assert.match(text, /Paid: €70\.00/);
});

