  const text = renderInvoiceText(issued);

  // Should NOT show a paid line (no payments yet)
  assert.doesNotMatch(text, /Paid:/);
});

test('renderInvoiceText shows all details together', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // Gold tier (5% discount)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 1 },
    ],
    terms: 'NET30',
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'PROMO', amount: 2000 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  const paid = recordPayment(issued, { amount: 15000, date: '2026-10-10' }).value;

  const text = renderInvoiceText(paid);

  // Check all components are present
  assert.match(text, /INV-2026-0001/);
  assert.match(text, /Northwind Studio/);
  assert.match(text, /Development/);
  assert.match(text, /Discount: €/); // line discount
  assert.match(text, /Voucher \(PROMO\):/);
  assert.match(text, /VAT:/);
  assert.match(text, /Total:/);
  assert.match(text, /Due: 2026-11-06/);
  assert.match(text, /Paid: €150\.00/);
});

test('renderInvoiceText output is readable and well-formatted', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 2 },
      { sku: 'STICKER', qty: 100 },
    ],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const paid = recordPayment(issued, { amount: 5000, date: '2026-10-10' }).value;

  const text = renderInvoiceText(paid);
  const lines = text.split('\n');

  // Check structure: header, customer, items, voucher (maybe), vat, total, due, paid
  assert(lines.length >= 7);
  assert.match(lines[0], /INV-2026-/);
  assert.match(lines[1], /Blue Fern Bakery/);
  assert.match(lines[lines.length - 1], /Paid:/);
  assert(text.indexOf('Total:') < text.indexOf('Due:'));
  assert(text.indexOf('Due:') < text.indexOf('Paid:'));
});

